 "<b style=\"font-size:24px;color:#5eead4\">Láseres</b><br><span style=\"font-size:20px;color:#f1ecff\">En lectores, cirugía y fibra óptica.</span>": "<b style=\"font-size:24px;color:#5eead4\">Lasers</b><br><span style=\"font-size:20px;color:#f1ecff\">Em leitores, cirurgia e fibra ótica.</span>",
